/**
 * @module use-mobile
 *
 * Hooks de detecção de dispositivo com histerese na faixa tablet.
 *
 * Modos suportados:
 * - `mobile`  → viewport &lt; 768px **OU** 768-1279px com aspect-ratio ≤ 10/11
 *               (tablets em retrato seguem layout mobile por escolha de produto)
 * - `tablet`  → viewport 768-1279px com aspect-ratio ≥ 11/10 (iPad, Surface deitado)
 *               **Zona morta** (10/11 &lt; ratio &lt; 11/10, aprox. quadrado): mantém o
 *               modo anterior (histerese) em vez de oscilar entre landscape/portrait.
 *               Isso elimina o flicker em tablets Android onde o viewport oscila
 *               quando a barra de URL aparece/some (dvh instability).
 * - `desktop` → viewport ≥ 1280px (qualquer orientação)
 *
 * Thresholds de aspect-ratio:
 * - "claramente paisagem" = ratio ≥ 11/10 (1.10) → tablet
 * - "claramente retrato"  = ratio ≤ 10/11 (0.909) → mobile
 * - "zona morta"          = 0.909 &lt; ratio &lt; 1.10 → sticky (prevMode ?? 'mobile')
 *
 * Verificação com os viewports dos testes:
 * - 1180×810 → 1.456 ≥ 1.10 → tablet ✓
 * - 810×1180 → 0.686 ≤ 0.909 → mobile ✓
 * - 1024×768 → 1.333 ≥ 1.10 → tablet ✓
 * - 768×1024 → 0.750 ≤ 0.909 → mobile ✓
 */

import * as React from 'react';
import { wideWarn } from '@/shared/lib/telemetry/wide-events';

/** Viewport máximo (exclusivo) considerado mobile sem condicionar orientação. */
const MOBILE_BREAKPOINT = 768;
/** Viewport máximo (exclusivo) da faixa tablet; daí em diante é desktop. */
const TABLET_BREAKPOINT = 1280;

export type DeviceMode = 'mobile' | 'tablet' | 'desktop';

/**
 * Classificação pura do modo de dispositivo a partir de dimensões numéricas e
 * do estado anterior (para histerese). Não acessa `window` — testável sem DOM.
 *
 * Exportada para testes unitários diretos da lógica de histerese.
 */
export function deviceModeFor(
  width: number,
  height: number,
  prev?: DeviceMode,
): DeviceMode {
  if (width < MOBILE_BREAKPOINT) return 'mobile';
  if (width >= TABLET_BREAKPOINT) return 'desktop';

  // Faixa 768–1279: decidir por aspect-ratio com zona morta.
  const ratio = height > 0 ? width / height : 1;

  // Claramente paisagem → tablet
  if (ratio >= 11 / 10) return 'tablet';
  // Claramente retrato → mobile
  if (ratio <= 10 / 11) return 'mobile';
  // Zona morta (quase-quadrado): manter estado anterior (histerese).
  if (prev === 'tablet' || prev === 'mobile') return prev;
  return 'mobile'; // primeira leitura sem histórico: default mobile
}

/**
 * Lê o modo atual usando `matchMedia.matches` (confiável durante orientationchange,
 * onde `window.innerWidth/Height` pode refletir a orientação anterior por ~100ms)
 * e aplica histerese via `deviceModeFor`.
 *
 * @param prevMode - Modo anterior; usado pela zona morta de histerese.
 */
function readDeviceMode(prevMode?: DeviceMode): DeviceMode {
  if (typeof window === 'undefined') return 'desktop';

  if (window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`).matches) {
    return 'mobile';
  }
  if (window.matchMedia(`(min-width: ${TABLET_BREAKPOINT}px)`).matches) {
    return 'desktop';
  }

  // Faixa 768–1279: aspect-ratio com histerese.
  if (window.matchMedia('(min-aspect-ratio: 11/10)').matches) return 'tablet';
  if (window.matchMedia('(max-aspect-ratio: 10/11)').matches) return 'mobile';

  // Zona morta: sticky.
  if (prevMode === 'tablet' || prevMode === 'mobile') return prevMode;
  return 'mobile';
}

/**
 * Retorna o modo de dispositivo atual: `mobile`, `tablet` ou `desktop`.
 * Reage a mudanças de viewport e orientação.
 *
 * Debounce de 150ms coalesce rajadas de `resize`/`orientationchange` em um único
 * setState, eliminando a dupla atualização que causava flicker em tablets Android.
 * A guarda de igualdade (`prev === next ? prev : next`) evita re-renders quando o
 * modo não muda de fato.
 */
export function useDeviceMode(): DeviceMode {
  const [mode, setMode] = React.useState<DeviceMode>(() => readDeviceMode());

  React.useLayoutEffect(() => {
    let debounceId: ReturnType<typeof setTimeout> | undefined;

    const scheduleUpdate = () => {
      if (debounceId !== undefined) clearTimeout(debounceId);
      debounceId = setTimeout(() => {
        debounceId = undefined;
        setMode((prev) => {
          const next = readDeviceMode(prev);
          return prev === next ? prev : next;
        });
      }, 150);
    };

    // Leitura inicial imediata (sem debounce), mas ainda com guarda de igualdade.
    setMode((prev) => {
      const next = readDeviceMode(prev);
      return prev === next ? prev : next;
    });

    const queries = [
      window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`),
      window.matchMedia(`(min-width: ${TABLET_BREAKPOINT}px)`),
      window.matchMedia('(min-aspect-ratio: 11/10)'),
      window.matchMedia('(max-aspect-ratio: 10/11)'),
    ];
    queries.forEach((mq) => mq.addEventListener('change', scheduleUpdate));
    window.addEventListener('resize', scheduleUpdate);
    window.addEventListener('orientationchange', scheduleUpdate);

    return () => {
      if (debounceId !== undefined) clearTimeout(debounceId);
      queries.forEach((mq) => mq.removeEventListener('change', scheduleUpdate));
      window.removeEventListener('resize', scheduleUpdate);
      window.removeEventListener('orientationchange', scheduleUpdate);
    };
  }, []);

  return mode;
}

/**
 * `true` quando o dispositivo deve usar layout mobile-essence.
 *
 * Filosofia: "essência mobile continua + adapta layout pra landscape". Por isso
 * inclui qualquer viewport não-desktop:
 *  - phones (&lt; 768px)
 *  - tablets em portrait (768-1279px, ratio ≤ 10/11)
 *  - **tablets em landscape** (768-1279px, ratio ≥ 11/10) — neste caso o
 *    JSX mobile é renderizado, mas com classes `tablet:` do Tailwind aplicadas
 *    para re-arranjar o layout para landscape (grids mais largos, side panels,
 *    typography maior). Use {@link useIsTablet} para diferenciar.
 *
 * Equivale a `useDeviceMode() !== 'desktop'`.
 */
export function useIsMobile(): boolean {
  return useDeviceMode() !== 'desktop';
}

/**
 * `true` quando o dispositivo está na faixa tablet em landscape
 * (768-1279px e aspect-ratio ≥ 11/10, fora da zona morta de histerese).
 */
export function useIsTablet(): boolean {
  return useDeviceMode() === 'tablet';
}

/**
 * Detecta se o dispositivo possui câmera disponível.
 *
 * Em dispositivos mobile, assume presença de câmera por compatibilidade.
 * Em desktop, enumera os media devices para verificar.
 */
export function useHasCamera(): { hasCamera: boolean; isChecking: boolean } {
  const [hasCamera, setHasCamera] = React.useState(false);
  const [isChecking, setIsChecking] = React.useState(true);

  React.useEffect(() => {
    const checkCamera = async () => {
      try {
        const userAgent = navigator.userAgent.toLowerCase();
        const isMobileDevice =
          /android|iphone|ipad|ipod|blackberry|windows phone/.test(userAgent);

        if (isMobileDevice) {
          setHasCamera(true);
          setIsChecking(false);
          return;
        }

        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
          setHasCamera(false);
          setIsChecking(false);
          return;
        }

        const devices = await navigator.mediaDevices.enumerateDevices();
        const videoDevices = devices.filter(
          (device) => device.kind === 'videoinput',
        );
        setHasCamera(videoDevices.length > 0);
      } catch (error) {
        wideWarn('device.camera_check_error', 'Erro ao verificar câmera', {
          attributes: {
            'error.message':
              error instanceof Error ? error.message : String(error),
            'device.has_media_devices': !!navigator.mediaDevices,
          },
        });
        const userAgent = navigator.userAgent.toLowerCase();
        const isMobileDevice =
          /android|iphone|ipad|ipod|blackberry|windows phone/.test(userAgent);
        setHasCamera(isMobileDevice);
      } finally {
        setIsChecking(false);
      }
    };

    checkCamera();
  }, []);

  return { hasCamera, isChecking };
}

