1	import { renderHook, waitFor, cleanup } from '@testing-library/react';
2	import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
3	import {
4	  useIsMobile,
5	  useIsTablet,
6	  useDeviceMode,
7	  useHasCamera,
8	  deviceModeFor,
9	} from './use-mobile';
10	
11	// ---------------------------------------------------------------------------
12	// Helpers de viewport
13	// ---------------------------------------------------------------------------
14	
15	function setViewport(width: number, height: number) {
16	  Object.defineProperty(window, 'innerWidth', {
17	    writable: true,
18	    configurable: true,
19	    value: width,
20	  });
21	  Object.defineProperty(window, 'innerHeight', {
22	    writable: true,
23	    configurable: true,
24	    value: height,
25	  });
26	}
27	
28	// ---------------------------------------------------------------------------
29	// matchMedia mock que avalia queries contra window.innerWidth/innerHeight
30	// ---------------------------------------------------------------------------
31	//
32	// Suporta:
33	//   (max-width: Npx)          → innerWidth <= N
34	//   (min-width: Npx)          → innerWidth >= N
35	//   (min-aspect-ratio: A/B)   → innerWidth/innerHeight >= A/B
36	//   (max-aspect-ratio: A/B)   → innerWidth/innerHeight <= A/B
37	//   (orientation: landscape)  → innerWidth > innerHeight
38	//   (orientation: portrait)   → innerHeight >= innerWidth
39	//
40	// Nota: .matches é snapshot avaliado no momento de matchMedia(query).
41	// Como os testes chamam setViewport() ANTES de renderHook(), a leitura
42	// é sempre consistente para a leitura inicial do hook.
43	//
44	// Importante: NÃO usar vi.fn() como o value raiz de matchMedia, pois
45	// vi.clearAllMocks() apaga o mockImplementation entre testes. A função
46	// wrapper é uma função normal; apenas os campos internos do FakeMQL usam
47	// vi.fn() para que o hook possa chamar addEventListener/removeEventListener.
48	
49	type FakeMQL = {
50	  matches: boolean;
51	  media: string;
52	  onchange: null;
53	  addEventListener: ReturnType<typeof vi.fn>;
54	  removeEventListener: ReturnType<typeof vi.fn>;
55	  addListener: ReturnType<typeof vi.fn>;
56	  removeListener: ReturnType<typeof vi.fn>;
57	  dispatchEvent: ReturnType<typeof vi.fn>;
58	};
59	
60	function evaluateMediaQuery(query: string): boolean {
61	  const w = window.innerWidth;
62	  const h = window.innerHeight;
63	
64	  // compound query com 'and' — avaliar partes recursivamente
65	  if (query.includes(' and ')) {
66	    return query
67	      .split(' and ')
68	      .map((p) => p.trim())
69	      .every((p) => evaluateMediaQuery(p));
70	  }
71	
72	  // (max-width: Npx)
73	  const maxWidth = query.match(/\(max-width:\s*(\d+(?:\.\d+)?)px\)/);
74	  if (maxWidth) return w <= Number(maxWidth[1]);
75	
76	  // (min-width: Npx)
77	  const minWidth = query.match(/\(min-width:\s*(\d+(?:\.\d+)?)px\)/);
78	  if (minWidth) return w >= Number(minWidth[1]);
79	
80	  // (min-aspect-ratio: A/B)
81	  const minAspect = query.match(
82	    /\(min-aspect-ratio:\s*(\d+(?:\.\d+)?)\/(\d+(?:\.\d+)?)\)/,
83	  );
84	  if (minAspect) {
85	    const threshold = Number(minAspect[1]) / Number(minAspect[2]);
86	    return h > 0 ? w / h >= threshold : true;
87	  }
88	
89	  // (max-aspect-ratio: A/B)
90	  const maxAspect = query.match(
91	    /\(max-aspect-ratio:\s*(\d+(?:\.\d+)?)\/(\d+(?:\.\d+)?)\)/,
92	  );
93	  if (maxAspect) {
94	    const threshold = Number(maxAspect[1]) / Number(maxAspect[2]);
95	    return h > 0 ? w / h <= threshold : false;
96	  }
97	
98	  // (orientation: landscape)
99	  if (query.includes('orientation: landscape')) return w > h;
100	  // (orientation: portrait)
101	  if (query.includes('orientation: portrait')) return h >= w;
102	
103	  // fallback: query desconhecida → false
104	  return false;
105	}
106	
107	function makeFakeMQL(query: string): FakeMQL {
108	  return {
109	    matches: evaluateMediaQuery(query),
110	    media: query,
111	    onchange: null,
112	    addEventListener: vi.fn(),
113	    removeEventListener: vi.fn(),
114	    addListener: vi.fn(),
115	    removeListener: vi.fn(),
116	    dispatchEvent: vi.fn(),
117	  };
118	}
119	
120	function installMatchMedia() {
121	  // Usar assignment direto (não Object.defineProperty) porque setup.ts define
122	  // matchMedia com writable:true mas configurable:false. O defineProperty com
123	  // configurable:true lança TypeError sobre configurable:false; a atribuição
124	  // direta funciona pois writable:true permite isso.
125	  //
126	  // Função normal (não vi.fn()) para que vi.clearAllMocks() não remova a
127	  // implementação entre testes. Os métodos internos do FakeMQL usam vi.fn()
128	  // para que o hook possa registrar addEventListener/removeEventListener.
129	  // @ts-expect-error window.matchMedia tem tipo estrito do jsdom
130	  window.matchMedia = (query: string): FakeMQL => makeFakeMQL(query);
131	}
132	
133	// ---------------------------------------------------------------------------
134	// Suite
135	// ---------------------------------------------------------------------------
136	
137	describe('use-mobile hooks', () => {
138	  let originalWidth: number;
139	  let originalHeight: number;
140	
141	  beforeEach(() => {
142	    originalWidth = window.innerWidth;
143	    originalHeight = window.innerHeight;
144	    installMatchMedia();
145	  });
146	
147	  afterEach(() => {
148	    // Desmontar todos os componentes montados por renderHook para remover
149	    // listeners de window que poderiam interferir com o próximo teste.
150	    cleanup();
151	    setViewport(originalWidth, originalHeight);
152	    vi.clearAllMocks();
153	  });
154	
155	  // -------------------------------------------------------------------------
156	  // useDeviceMode — classificação estática
157	  // -------------------------------------------------------------------------
158	  describe('useDeviceMode', () => {
159	    it('classifies viewport < 768 as mobile (any orientation)', () => {
160	      setViewport(500, 900);
161	      const { result } = renderHook(() => useDeviceMode());
162	      expect(result.current).toBe('mobile');
163	    });
