import { renderHook, waitFor, cleanup } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import {
  useIsMobile,
  useIsTablet,
  useDeviceMode,
  useHasCamera,
  deviceModeFor,
} from './use-mobile';

// ---------------------------------------------------------------------------
// Helpers de viewport
// ---------------------------------------------------------------------------

function setViewport(width: number, height: number) {
  Object.defineProperty(window, 'innerWidth', {
    writable: true,
    configurable: true,
    value: width,
  });
  Object.defineProperty(window, 'innerHeight', {
    writable: true,
    configurable: true,
    value: height,
  });
}

// ---------------------------------------------------------------------------
// matchMedia mock que avalia queries contra window.innerWidth/innerHeight
// ---------------------------------------------------------------------------
//
// Suporta:
//   (max-width: Npx)          → innerWidth <= N
//   (min-width: Npx)          → innerWidth >= N
//   (min-aspect-ratio: A/B)   → innerWidth/innerHeight >= A/B
//   (max-aspect-ratio: A/B)   → innerWidth/innerHeight <= A/B
//   (orientation: landscape)  → innerWidth > innerHeight
//   (orientation: portrait)   → innerHeight >= innerWidth
//
// Nota: .matches é snapshot avaliado no momento de matchMedia(query).
// Como os testes chamam setViewport() ANTES de renderHook(), a leitura
// é sempre consistente para a leitura inicial do hook.
//
// Importante: NÃO usar vi.fn() como o value raiz de matchMedia, pois
// vi.clearAllMocks() apaga o mockImplementation entre testes. A função
// wrapper é uma função normal; apenas os campos internos do FakeMQL usam
// vi.fn() para que o hook possa chamar addEventListener/removeEventListener.

type FakeMQL = {
  matches: boolean;
  media: string;
  onchange: null;
  addEventListener: ReturnType<typeof vi.fn>;
  removeEventListener: ReturnType<typeof vi.fn>;
  addListener: ReturnType<typeof vi.fn>;
  removeListener: ReturnType<typeof vi.fn>;
  dispatchEvent: ReturnType<typeof vi.fn>;
};

function evaluateMediaQuery(query: string): boolean {
  const w = window.innerWidth;
  const h = window.innerHeight;

  // compound query com 'and' — avaliar partes recursivamente
  if (query.includes(' and ')) {
    return query
      .split(' and ')
      .map((p) => p.trim())
      .every((p) => evaluateMediaQuery(p));
  }

  // (max-width: Npx)
  const maxWidth = query.match(/\(max-width:\s*(\d+(?:\.\d+)?)px\)/);
  if (maxWidth) return w <= Number(maxWidth[1]);

  // (min-width: Npx)
  const minWidth = query.match(/\(min-width:\s*(\d+(?:\.\d+)?)px\)/);
  if (minWidth) return w >= Number(minWidth[1]);

  // (min-aspect-ratio: A/B)
  const minAspect = query.match(
    /\(min-aspect-ratio:\s*(\d+(?:\.\d+)?)\/(\d+(?:\.\d+)?)\)/,
  );
  if (minAspect) {
    const threshold = Number(minAspect[1]) / Number(minAspect[2]);
    return h > 0 ? w / h >= threshold : true;
  }

  // (max-aspect-ratio: A/B)
  const maxAspect = query.match(
    /\(max-aspect-ratio:\s*(\d+(?:\.\d+)?)\/(\d+(?:\.\d+)?)\)/,
  );
  if (maxAspect) {
    const threshold = Number(maxAspect[1]) / Number(maxAspect[2]);
    return h > 0 ? w / h <= threshold : false;
  }

  // (orientation: landscape)
  if (query.includes('orientation: landscape')) return w > h;
  // (orientation: portrait)
  if (query.includes('orientation: portrait')) return h >= w;

  // fallback: query desconhecida → false
  return false;
}

function makeFakeMQL(query: string): FakeMQL {
  return {
    matches: evaluateMediaQuery(query),
    media: query,
    onchange: null,
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
    addListener: vi.fn(),
    removeListener: vi.fn(),
    dispatchEvent: vi.fn(),
  };
}

function installMatchMedia() {
  // Usar assignment direto (não Object.defineProperty) porque setup.ts define
  // matchMedia com writable:true mas configurable:false. O defineProperty com
  // configurable:true lança TypeError sobre configurable:false; a atribuição
  // direta funciona pois writable:true permite isso.
  //
  // Função normal (não vi.fn()) para que vi.clearAllMocks() não remova a
  // implementação entre testes. Os métodos internos do FakeMQL usam vi.fn()
  // para que o hook possa registrar addEventListener/removeEventListener.
  // @ts-expect-error window.matchMedia tem tipo estrito do jsdom
  window.matchMedia = (query: string): FakeMQL => makeFakeMQL(query);
}

// ---------------------------------------------------------------------------
// Suite
// ---------------------------------------------------------------------------

describe('use-mobile hooks', () => {
  let originalWidth: number;
  let originalHeight: number;

  beforeEach(() => {
    originalWidth = window.innerWidth;
    originalHeight = window.innerHeight;
    installMatchMedia();
  });

  afterEach(() => {
    // Desmontar todos os componentes montados por renderHook para remover
    // listeners de window que poderiam interferir com o próximo teste.
    cleanup();
    setViewport(originalWidth, originalHeight);
    vi.clearAllMocks();
  });

  // -------------------------------------------------------------------------
  // useDeviceMode — classificação estática
  // -------------------------------------------------------------------------
  describe('useDeviceMode', () => {
    it('classifies viewport < 768 as mobile (any orientation)', () => {
      setViewport(500, 900);
      const { result } = renderHook(() => useDeviceMode());
      expect(result.current).toBe('mobile');
    });

    it('classifies viewport >= 1280 as desktop', () => {
      setViewport(1440, 900);
      const { result } = renderHook(() => useDeviceMode());
      expect(result.current).toBe('desktop');
    });

    it('classifies 768-1279 in landscape as tablet', () => {
      setViewport(1180, 810); // ratio 1.456 >= 1.10 → tablet
      const { result } = renderHook(() => useDeviceMode());
      expect(result.current).toBe('tablet');
    });

    it('classifies 768-1279 in portrait as mobile', () => {
      setViewport(810, 1180); // ratio 0.686 <= 0.909 → mobile
      const { result } = renderHook(() => useDeviceMode());
      expect(result.current).toBe('mobile');
    });

    it('boundary: 1280×800 landscape is desktop, not tablet', () => {
      setViewport(1280, 800);
      const { result } = renderHook(() => useDeviceMode());
      expect(result.current).toBe('desktop');
    });
  });

  // -------------------------------------------------------------------------
  // useIsMobile
  // -------------------------------------------------------------------------
  describe('useIsMobile', () => {
    // Contrato: useIsMobile === (useDeviceMode() !== 'desktop'). Tablet (landscape
    // ou portrait) é "mobile-essence" e renderiza o JSX mobile — só desktop é false.
    // useIsTablet() é quem diferencia tablet landscape de phone. Ver JSDoc do hook.
    it('returns true for tablet landscape (mobile-essence: tablet ≠ desktop)', () => {
      setViewport(1180, 810);
      const { result } = renderHook(() => useIsMobile());
      expect(result.current).toBe(true);
    });

    it('returns true for tiny phones', () => {
      setViewport(375, 812);
      const { result } = renderHook(() => useIsMobile());
      expect(result.current).toBe(true);
    });

    it('returns true for tablet portrait (essence-of-mobile spec)', () => {
      setViewport(810, 1180);
      const { result } = renderHook(() => useIsMobile());
      expect(result.current).toBe(true);
    });

    it('returns false for desktop', () => {
      setViewport(1440, 900);
      const { result } = renderHook(() => useIsMobile());
      expect(result.current).toBe(false);
    });
  });

  // -------------------------------------------------------------------------
  // useIsTablet
  // -------------------------------------------------------------------------
  describe('useIsTablet', () => {
    it('returns true only for tablet landscape range', () => {
      setViewport(1024, 768); // ratio 1.333 >= 1.10 → tablet
      const { result } = renderHook(() => useIsTablet());
      expect(result.current).toBe(true);
    });

    it('returns false for tablet portrait', () => {
      setViewport(768, 1024); // ratio 0.750 <= 0.909 → mobile
      const { result } = renderHook(() => useIsTablet());
      expect(result.current).toBe(false);
    });

    it('returns false for desktop landscape', () => {
      setViewport(1920, 1080);
      const { result } = renderHook(() => useIsTablet());
      expect(result.current).toBe(false);
    });
  });

  // -------------------------------------------------------------------------
  // Histerese — deviceModeFor (lógica pura, sem matchMedia)
  //
  // Testa diretamente a função exportada para validar a zona morta sem precisar
  // simular eventos de resize no DOM. A lógica de histerese é separada do DOM
  // intencionalmente via `deviceModeFor(width, height, prev?)`.
  // -------------------------------------------------------------------------
  describe('deviceModeFor (histerese — lógica pura)', () => {
    it('near-square viewport starting as tablet stays tablet (sticky)', () => {
      // 900×880 → ratio 1.023 (zona morta 0.909–1.10) com prev=tablet
      expect(deviceModeFor(900, 880, 'tablet')).toBe('tablet');
    });

    it('near-square viewport starting as mobile stays mobile (sticky)', () => {
      // 900×880 → ratio 1.023 (zona morta) com prev=mobile
      expect(deviceModeFor(900, 880, 'mobile')).toBe('mobile');
    });

    it('near-square without history defaults to mobile', () => {
      // Primeira leitura sem histórico na zona morta → mobile
      expect(deviceModeFor(900, 880, undefined)).toBe('mobile');
    });

    it('clearly landscape (ratio >= 1.10) always tablet regardless of prev', () => {
      // 1180×810 → ratio 1.456 — claramente paisagem, ignora prev=mobile
      expect(deviceModeFor(1180, 810, 'mobile')).toBe('tablet');
    });

    it('clearly portrait (ratio <= 0.909) always mobile regardless of prev', () => {
      // 810×1180 → ratio 0.686 — claramente retrato, ignora prev=tablet
      expect(deviceModeFor(810, 1180, 'tablet')).toBe('mobile');
    });

    it('boundary 11/10 (ratio exactly 1.10) is tablet', () => {
      // 1100×1000 → ratio exatamente 1.10 na faixa tablet (768–1279)
      expect(deviceModeFor(1100, 1000, undefined)).toBe('tablet');
    });

    it('boundary 10/11 (ratio exactly 0.909…) is mobile', () => {
      // 1000×1100 → ratio 0.909… na faixa tablet → mobile
      expect(deviceModeFor(1000, 1100, undefined)).toBe('mobile');
    });

    it('viewport < 768 is always mobile regardless of ratio or prev', () => {
      // landscape mas < 768 → phone, não tablet
      expect(deviceModeFor(600, 400, 'tablet')).toBe('mobile');
    });

    it('viewport >= 1280 is always desktop regardless of ratio or prev', () => {
      expect(deviceModeFor(1280, 720, 'tablet')).toBe('desktop');
      expect(deviceModeFor(1440, 900, 'mobile')).toBe('desktop');
    });
  });

  // -------------------------------------------------------------------------
  // useHasCamera
  // -------------------------------------------------------------------------
  describe('useHasCamera', () => {
    let originalNavigator: typeof navigator;

    beforeEach(() => {
      originalNavigator = navigator;
    });

    afterEach(() => {
      Object.defineProperty(window, 'navigator', {
        value: originalNavigator,
        configurable: true,
        writable: true,
      });
    });

    it('identifies mobile device based on userAgent and resolves true implicitly', async () => {
      Object.defineProperty(window, 'navigator', {
        value: {
          userAgent: 'Mozilla/5.0 (iPhone; CPU iPhone OS 10_3 like Mac OS X)',
        },
        configurable: true,
        writable: true,
      });

      const { result } = renderHook(() => useHasCamera());

      await waitFor(() => {
        expect(result.current.isChecking).toBe(false);
      });

      expect(result.current.hasCamera).toBe(true);
    });

    it('checks mediaDevices for desktop and finds a videoinput', async () => {
      const mockEnumerateDevices = vi.fn().mockResolvedValue([
        { kind: 'videoinput', deviceId: '123' },
        { kind: 'audioinput', deviceId: '456' },
      ]);

      Object.defineProperty(window, 'navigator', {
        value: {
          userAgent: 'Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7)',
          mediaDevices: {
            getUserMedia: vi.fn(),
            enumerateDevices: mockEnumerateDevices,
          },
        },
        configurable: true,
        writable: true,
      });

      const { result } = renderHook(() => useHasCamera());

      await waitFor(() => {
        expect(result.current.isChecking).toBe(false);
      });

      expect(result.current.hasCamera).toBe(true);
    });

    it('handles lack of mediaDevices API gracefully', async () => {
      Object.defineProperty(window, 'navigator', {
        value: {
          userAgent: 'Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7)',
        },
        configurable: true,
        writable: true,
      });

      const { result } = renderHook(() => useHasCamera());

      await waitFor(() => {
        expect(result.current.isChecking).toBe(false);
      });

      expect(result.current.hasCamera).toBe(false);
    });
  });
});

